option.value:
body {
    margin: 0;
    font-family: Arial, sans-serif;
}

.site-header {
    border-bottom: 1px solid #e5e7eb;
    background-color: #ffffff;
}

.navbar {
    width: 100%;
    margin: 0;
    padding: 12px 16px;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
}

.nav-left {
    display: flex;
    align-items: center;
    gap: 20px;
}

.brand {
    display: inline-flex;
    align-items: center;
}

.logo {
    width: 50px;
    height: auto;
    display: block;
}

.quick-links {
    display: flex;
    align-items: center;
    gap: 16px;
}

.quick-links a,
.login-link {
    color: #1f2937;
    text-decoration: none;
    font-weight: 600;
}

.quick-links a:hover,
.login-link:hover {
    text-decoration: underline;
}

.login-link {
    margin-left: 0;
    white-space: nowrap;
}

body {
    margin: 0;
    font-family: Arial, sans-serif;
}

.site-header {
    border-bottom: 1px solid #e5e7eb;
    background-color: #ffffff;
}

.navbar {
    width: 100%;
