    gap: 32px;
}

.brand {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    color: #111827;
    text-decoration: none;
}

.brand-text {
    font-size: 18px;
    font-weight: 700;
    line-height: 1;
}

.logo {
    width: 50px;
    height: auto;
    display: block;
}

.quick-links {
    display: flex;
    align-items: center;
    gap: 16px;
}

.quick-links a,
.login-link {
    color: #1f2937;
    text-decoration: none;
    font-weight: 600;
}

.quick-links a:hover,
